          "ui",
          "api-app",
          "api-trpc",
          "api-procedures"
        ]
      },
      // The domain is pure: it imports no other role by value.
      {
        "from": "api-domain",
        "allow": [],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-integrations"
        ]
